def tail_sum_mean(p, terms):
    """Partial sum of (1 - p)^k for k = 0 .. terms - 1."""
    return sum((1 - p) ** k for k in range(terms))

def years_to_reach(d, g, r, frac):
    """Smallest n whose partial sum of d(1+g)^(k-1)/(1+r)^k reaches frac of d/(r-g)."""
    if g >= r or not 0 < frac < 1:
        raise ValueError("need g < r and 0 < frac < 1")
    target = frac * d / (r - g)
    total = 0.0
    n = 0
    while total < target:
        n += 1
        total += d * (1 + g) ** (n - 1) / (1 + r) ** n
    return n
